import{_ as e,o as d,c as o,a0 as a}from"./chunks/framework.C3yZ6M33.js";const u=JSON.parse('{"title":"HTTP API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api.md","filePath":"reference/api.md"}'),s={name:"reference/api.md"};function r(i,t,n,c,p,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="http-api" tabindex="-1">HTTP API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP API&quot;">​</a></h1><p><code>peregrin serve</code> composes two route sets under one listener: the <strong>session routes</strong> (peregrin&#39;s integration surface) and the <strong>generic entity routes</strong> (the hypha substrate — <code>/api/entities*</code>, pairing, auth, push, fs). <code>peregrin-hub</code> exposes the same generic surface merged across nodes, plus <code>/api/node-status</code>.</p><h2 id="identity-and-health" tabindex="-1">Identity and health <a class="header-anchor" href="#identity-and-health" aria-label="Permalink to &quot;Identity and health&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /api/health</code></td><td>Liveness + store readability</td></tr><tr><td><code>GET /api/node</code></td><td>Node identity, agents, capabilities (incl. <code>PEREGRIN_RUNNER_LABELS</code>)</td></tr><tr><td><code>PATCH /api/node</code></td><td>Rename the node (persisted to <code>PEREGRIN_NODE</code>)</td></tr><tr><td><code>GET /api/user</code></td><td>OS user the node runs as</td></tr><tr><td><code>GET /api/fs</code></td><td>Subdirectory listing for a path</td></tr><tr><td><code>GET /api/events</code></td><td>SSE feed — session/meta/project/heartbeat</td></tr><tr><td><code>GET /api/agents</code></td><td>Agent runtimes registered on the plane</td></tr><tr><td><code>GET /api/client/keypair</code></td><td>Client keypair for the entity plane</td></tr></tbody></table><h2 id="pairing-and-auth" tabindex="-1">Pairing and auth <a class="header-anchor" href="#pairing-and-auth" aria-label="Permalink to &quot;Pairing and auth&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST /api/pair</code></td><td>Trade a one-time code for a bearer credential (<code>sepia_…</code>); rate-limited</td></tr><tr><td><code>POST /api/auth/login</code> / <code>POST /api/auth/logout</code></td><td>Cookie session flow</td></tr><tr><td><code>GET /api/push/vapid</code> / <code>POST /api/push/subscribe</code></td><td>Web-push keys and subscriptions</td></tr></tbody></table><p><code>Authorization: Bearer &lt;token&gt;</code> guards non-loopback binds; <code>?access_token=</code> works only on the SSE paths.</p><h2 id="entities-generic-substrate" tabindex="-1">Entities (generic substrate) <a class="header-anchor" href="#entities-generic-substrate" aria-label="Permalink to &quot;Entities (generic substrate)&quot;">​</a></h2><p>Kind-agnostic entity plane — sessions register as <code>kind=&quot;sepia-session&quot;</code>, campaigns as <code>kind=&quot;campaign&quot;</code>. Op kinds are namespaced (<code>sepia.prompt</code>, <code>campaign.start</code>, <code>entity.delete</code>); snapshot bytes are opaque end-to-end.</p><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /api/entities</code></td><td>Entity index list (<code>?kind=</code> filters)</td></tr><tr><td><code>POST /api/entities</code></td><td>Create an entity (<code>{id?, kind, indexDoc}</code>)</td></tr><tr><td><code>GET /api/entities/snapshot</code></td><td>Bulk snapshot export</td></tr><tr><td><code>POST /api/entities/snapshot</code></td><td>Snapshot import (kind-shaped bytes, <code>?node=</code> on hubs)</td></tr><tr><td><code>GET /api/entities/{id}</code></td><td>Entity detail</td></tr><tr><td><code>DELETE /api/entities/{id}</code></td><td>Delete (<code>entity.delete</code> op)</td></tr><tr><td><code>POST /api/entities/{id}/ops</code></td><td>Submit a namespaced op (<code>{op, params}</code>)</td></tr><tr><td><code>GET /api/entities/{id}/snapshot</code></td><td>Single-entity snapshot export</td></tr><tr><td><code>GET /api/entity-index</code></td><td>Projection index document</td></tr><tr><td><code>GET /api/pending-ops</code></td><td>Durable outbox depth (hub: real; bare node: empty)</td></tr></tbody></table><h2 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /api/sessions</code></td><td>Merged list (<code>?locks=1</code> probes live holders)</td></tr><tr><td><code>GET /api/sessions/:id</code></td><td>Session detail or summary</td></tr><tr><td><code>GET /api/sessions/:id/meta</code></td><td>Overlay meta (title/pin/projects/spans)</td></tr><tr><td><code>GET /api/sessions/:id/history</code></td><td>Paginated history</td></tr><tr><td><code>GET /api/sessions/:id/checkpoints</code></td><td>Checkpoint refs</td></tr><tr><td><code>GET /api/sessions/:id/export</code></td><td>Session IR JSON</td></tr><tr><td><code>GET /api/sessions/:id/stream</code></td><td>SSE stream for one session</td></tr><tr><td><code>GET /api/sessions/:id/permissions</code></td><td>Pending permission requests</td></tr><tr><td><code>POST /api/sessions</code></td><td>Create (<code>cwd</code>, <code>agent</code>, <code>title</code>, <code>model</code>)</td></tr><tr><td><code>POST /api/sessions/import</code></td><td>Import IR or <code>history</code> array → store</td></tr><tr><td><code>POST /api/sessions/:id/prompt</code></td><td>Send a turn to an attached session</td></tr><tr><td><code>POST /api/sessions/:id/attach</code></td><td>Attach (<code>takeover</code> preempts live holder)</td></tr><tr><td><code>POST /api/sessions/:id/detach</code></td><td>Release a held session</td></tr><tr><td><code>POST /api/sessions/:id/cancel</code></td><td>Cancel a running turn</td></tr><tr><td><code>POST /api/sessions/:id/permission</code></td><td>Resolve a permission request</td></tr><tr><td><code>POST /api/sessions/:id/restore</code></td><td>Restore files to a checkpoint</td></tr><tr><td><code>POST /api/sessions/:id/rewind</code></td><td>Rewind the session tree</td></tr><tr><td><code>POST /api/sessions/:id/convert</code></td><td>Copy into another agent&#39;s store</td></tr><tr><td><code>DELETE /api/sessions/:id</code></td><td>Delete from the owning store</td></tr><tr><td><code>PATCH /api/sessions/:id</code></td><td>Rename / pin / archive (overlay meta)</td></tr></tbody></table><h2 id="projects-and-config" tabindex="-1">Projects and config <a class="header-anchor" href="#projects-and-config" aria-label="Permalink to &quot;Projects and config&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /api/projects</code></td><td>Node-local project grouping of sessions</td></tr><tr><td><code>GET /api/projects/:id</code></td><td>One project</td></tr><tr><td><code>GET /api/config</code></td><td>Agent config IR (rules, skills, hooks, MCP)</td></tr><tr><td><code>GET/PUT /api/config/:key</code></td><td>One config item</td></tr></tbody></table><h2 id="hub-only" tabindex="-1">Hub-only <a class="header-anchor" href="#hub-only" aria-label="Permalink to &quot;Hub-only&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /api/node-status</code></td><td>Per-node health across the fleet</td></tr></tbody></table><p>The hub also merges <code>/api/entities*</code> across nodes and proxies SSE / passthrough to the owning node.</p><h2 id="auth-and-errors" tabindex="-1">Auth and errors <a class="header-anchor" href="#auth-and-errors" aria-label="Permalink to &quot;Auth and errors&quot;">​</a></h2><p>Non-loopback nodes require <code>Authorization: Bearer &lt;PEREGRIN_TOKEN&gt;</code> (hub: <code>PEREGRIN_HUB_TOKEN</code>). Session-route errors are JSON <code>{ &quot;error&quot;, &quot;code&quot; }</code> — <code>not_found</code>, <code>invalid</code>, <code>unknown_agent</code>, <code>locked</code> (a live holder blocks the op; pass <code>takeover</code>), <code>conflict</code>, <code>busy</code>, <code>internal</code>. Generic entity-route errors use hypha&#39;s <code>{error}</code> mapping, not the session shape.</p>',19)])])}const b=e(s,[["render",r]]);export{u as __pageData,b as default};
